import { isoOrNull, stableId } from '../core/contracts.js';
export async function normalizeNewsArticle(input={},placeResolver=null){if(!input.title||!input.source||!input.url)return null;let resolved=null;if(Number.isFinite(input.lat)&&Number.isFinite(input.lon))resolved={lat:input.lat,lon:input.lon,precision:'EXACT_SOURCE'};else if(placeResolver&&input.placeText)resolved=await placeResolver(input.placeText);return Object.freeze({articleId:input.articleId||stableId([input.source,input.url]),title:String(input.title),source:String(input.source),url:String(input.url),publishedAt:isoOrNull(input.publishedAt),category:input.category||'GENERAL',placeText:input.placeText||null,lat:Number.isFinite(resolved?.lat)?resolved.lat:null,lon:Number.isFinite(resolved?.lon)?resolved.lon:null,locationPrecision:resolved?.precision||'NONE',mappable:Number.isFinite(resolved?.lat)&&Number.isFinite(resolved?.lon),truthClass:'NEWS_REPORT'});}
export async function normalizeNewsBatch(rows=[],resolver=null){const out=[];for(const row of rows){const n=await normalizeNewsArticle(row,resolver);if(n)out.push(n);}return out;}
